#!/bin/bash
# بروزرسانی توضیحات فارسی Release v2.11.0
set -e
TOKEN=$(git config remote.origin.url | grep -oP '(?<=://)[^@]+(?=@)' | cut -d: -f2)
REPO="021hk/modiriat-hesab"
TAG="v2.11.0"

REL_ID=$(curl -s -H "Authorization: token $TOKEN" "https://api.github.com/repos/$REPO/releases/tags/$TAG" | python3 -c "import json,sys; print(json.load(sys.stdin)['id'])")
echo "release id: $REL_ID"

cat > /tmp/release-body-v211.json <<'EOF'
{
  "body": "## تغییرات نسخه ۲.۱۱.۰ — بازطراحی کامل بدهی/طلب + عنوان خودکار تراکنش‌ها\n\n### ۱) کارت شخص در بدهی‌ها — مثل دفتر قدیم\n- حالا برای هر **شخص** یک کارت دارید (نه هر رکورد): اول **نام شخص**، بعد **گردش بدهی** (کل قرضی که از او گرفته‌اید) و **گردش طلب** (کل قرضی که به او داده‌اید) و در آخر **وضعیت نهایی**: «طلب دارید»، «بدهی دارید» یا «تسویه شده» — با مانده دقیق.\n- اگر یک شخص هم رکورد طلب داشته باشد هم بدهی، هر دو در یک کارت جمع می‌شوند (نشان «۲ رکورد») و از منوی ⋮ می‌توانید هر رکورد را جدا ویرایش/تسویه/حذف کنید.\n\n### ۲) ریز جزئیات هر شخص\n- دکمه «ریز جزئیات» باز می‌شود و نشان می‌دهد **چقد پرداخت و چقد برداشت/دریافت شده**:\n  - جمع برداشت‌ها (پرداخت به او) و جمع واریزها (دریافت از او) با تعداد موارد\n  - فهرست تک‌تک تراکنش‌های متصل با تاریخ و عنوان خودشان\n- اگر تراکنش بانکی متصلی نباشد، راهنمای ثبت از تب تراکنش‌ها نشان داده می‌شود.\n\n### ۳) عنوان خودکار تراکنش‌های بدهی/طلب ⭐\n- دیگر لازم نیست حالت را دستی انتخاب کنید! با وارد کردن نام شخص، عنوان تراکنش **از وضعیت فعلی همان شخص خودکار تشخیص داده می‌شود**:\n  - **برداشت** → اگر به او بدهکارید: «**پرداخت بدهی**»، وگرنه: «**پرداخت قرض**» (قرض دادن)\n  - **واریز** → اگر او به شما بدهکار است: «**دریافت طلب**»، وگرنه: «**دریافت بدهی**» (قرض گرفتن)\n- عنوان انتخاب‌شده قبل از ثبت با کادر «عنوان ثبت: ...» نمایش داده می‌شود و همان عنوان در لیست تراکنش‌ها و داشبورد کنار نام شخص می‌نشیند.\n- اگر تشخیص خودکار را نخواستید، با «تشخیص دستی» حالت دیگر را انتخاب کنید یا به حالت خودکار برگردید.\n\n### ۴) بهبودهای دیگر\n- فیلترهای «بدهکاران» و «طلبکاران» حالا روی اشخاص اعمال می‌شوند (نه رکوردها) — یعنی دقیقاً کسانی که به شما بدهکارند یا به آن‌ها بدهکارید.\n- کارت «وضعیت فعلی شما» (تشخیص خودکار) مثل قبل بالای تب هست و حالا با کارت‌های جدید هماهنگ است.\n\n---\n\n**نصب:** APK را دانلود و نصب کنید. اگر نسخه قبلی را دارید، معمولاً روی همان نصب می‌شود؛ اگر خطای «برنامه نصب نشد» دیدید، نسخه قبلی را حذف و این نسخه را نصب کنید.\n\n**Full Changelog**: https://github.com/021hk/modiriat-hesab/compare/v2.10.0...v2.11.0"
}
EOF

curl -s -X PATCH \
  -H "Authorization: token $TOKEN" \
  -H "Content-Type: application/json" \
  -d @/tmp/release-body-v211.json \
  "https://api.github.com/repos/$REPO/releases/$REL_ID" | python3 -c "import json,sys; r=json.load(sys.stdin); print('OK — body len:', len(r.get('body','')))"
